+++ b/src/media_tools/crypt_tools.c
@@ -569,6 +569,10 @@
 					gf_free(hls);
 			}
 		}
+	}
+	if (!drm_list && parser) {
+		gf_xml_dom_del(parser);
+		parser = NULL;
 	}

 exit:
